// Static checks for the display-only bundle. No DOM, no network, no engine.
// Run with: node scripts/check-bundle.mjs

import assert from 'node:assert/strict';
import { existsSync, mkdirSync, mkdtempSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { readFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

const root = process.cwd();
const readJson = async (relative) => JSON.parse(await readFile(path.join(root, relative), 'utf8'));

const pkg = await readJson('package.json');
assert.equal(pkg.name, '@dhr2333/dsh-ledger');
assert.equal(pkg.type, 'module');
assert.equal(pkg.dsh?.bundle?.patch, './cordis.patch.yml');
assert.equal(pkg.dsh?.client?.platform, 'web');
// The published tarball must be usable from the plugin market alone: the
// vendored ledger template is generated by prepack, not fetched by DSH after
// installation. The Python core is installed from its own PyPI wheel instead.
assert.equal(pkg.scripts?.prepack, 'node scripts/vendor.mjs', 'prepack must vendor the ledger template');
assert.ok(pkg.files?.includes('vendor'), 'package files must include vendor');

// The core is a separate PyPI distribution; the runtime wheelhouse pins the
// baseline so a first install works offline.
const runtimes = await readJson('scripts/runtimes.json');
assert.equal(runtimes.core?.package, 'beancount-guard', 'runtimes.json must pin the core package');
assert.match(runtimes.core?.version ?? '', /^\d+\.\d+\.\d+/, 'runtimes.json must pin a core version');

// Every supported platform gets an exact-version runtime package; npm installs
// only the one matching the host and the panel falls back to system Python when
// none resolves.
const RUNTIME_KEYS = ['win32-x64', 'win32-arm64', 'darwin-x64', 'darwin-arm64', 'linux-x64', 'linux-arm64'];
assert.deepEqual(
  Object.keys(pkg.optionalDependencies ?? {}).sort(),
  RUNTIME_KEYS.map((key) => `@dhr2333/dsh-ledger-runtime-${key}`).sort(),
  'optionalDependencies must list every runtime package',
);
for (const [name, version] of Object.entries(pkg.optionalDependencies)) {
  assert.equal(version, pkg.version, `${name} must match the plugin version`);
}

const platform = await import(pathToFileURL(path.join(root, 'src/host/platform.js')).href);
assert.equal(
  platform.venvProgram('/v', 'python', 'win32'),
  path.join('/v', 'Scripts', 'python.exe'),
  'Windows virtualenvs keep programs in Scripts with .exe',
);
assert.equal(
  platform.venvProgram('/v', 'bean-check', 'linux'),
  path.join('/v', 'bin', 'bean-check'),
  'POSIX virtualenvs keep programs in bin',
);
assert.equal(platform.runtimePackageName('win32', 'x64'), '@dhr2333/dsh-ledger-runtime-win32-x64');
assert.equal(platform.runtimePackageName('linux', 'arm64'), '@dhr2333/dsh-ledger-runtime-linux-arm64');
assert.equal(platform.runtimePython('/r', 'win32'), path.join('/r', 'python.exe'));
assert.equal(platform.runtimePython('/r', 'darwin'), path.join('/r', 'bin', 'python3'));

// npm pack drops symlinks, so an installed runtime keeps only the versioned
// binary. Resolution must still find it, and must prefer the conventional name
// when the links are present.
const fixture = mkdtempSync(path.join(os.tmpdir(), 'dsh-ledger-platform-'));
try {
  const bin = path.join(fixture, 'bin');
  mkdirSync(bin, { recursive: true });
  writeFileSync(path.join(bin, 'python3.13'), '');
  writeFileSync(path.join(bin, 'python3.12'), '');
  assert.equal(
    platform.runtimePython(fixture, 'linux'),
    path.join(bin, 'python3.13'),
    'a runtime without symlinks must resolve the newest versioned binary',
  );
  writeFileSync(path.join(bin, 'python3'), '');
  assert.equal(
    platform.runtimePython(fixture, 'linux'),
    path.join(bin, 'python3'),
    'a developer build with symlinks keeps using bin/python3',
  );
  rmSync(path.join(bin, 'python3'));
  rmSync(path.join(bin, 'python3.13'));
  rmSync(path.join(bin, 'python3.12'));
  assert.equal(
    platform.runtimePython(fixture, 'linux'),
    path.join(bin, 'python3'),
    'an empty bin/ keeps the conventional path instead of throwing',
  );
} finally {
  rmSync(fixture, { recursive: true, force: true });
}

for (const relative of [
  'index.js',
  'client.js',
  'cordis.patch.yml',
  'docs/DETAIL.md',
  'icon.svg',
  'src/options.js',
  'src/host/platform.js',
  'src/host/routes.js',
  'src/host/engine.js',
]) {
  assert.ok(existsSync(path.join(root, relative)), `missing ${relative}`);
}

const patch = await readFile(path.join(root, 'cordis.patch.yml'), 'utf8');
assert.ok(patch.includes("name: '@dhr2333/dsh-ledger'"), 'patch must insert this bundle');
// The patch ships with the plugin into every profile, so it must stay
// machine-neutral: personal paths belong in the profile's own patch layer.
assert.doesNotMatch(patch, /\/(?:home|Users|root)\//, 'bundle patch must not ship machine-specific paths');
for (const source of ['index.js', 'client.js', 'src/host/routes.js', 'src/host/engine.js']) {
  const text = await readFile(path.join(root, source), 'utf8');
  assert.ok(!text.includes('tools.register'), `${source} must not register agent tools`);
}

for (const locale of ['zh', 'en']) {
  const document = await readJson(`locale/${locale}.json`);
  assert.ok(document.meta?.title, `${locale} meta.title missing`);
  assert.ok(document.meta?.description, `${locale} meta.description missing`);
  assert.ok(existsSync(path.join(root, document.meta.detail)), `${locale} detail missing`);
}
const icon = await readFile(path.join(root, 'icon.svg'), 'utf8');
assert.match(icon, /^<svg\b/, 'icon must be SVG');
assert.match(icon, /viewBox=/, 'icon must have a viewBox');

// Discovery must know about the package-local copy; otherwise an npm install
// still needs a hand-made source checkout.
for (const source of ['src/options.js', 'src/host/init.js']) {
  assert.match(await readFile(path.join(root, source), 'utf8'), /'vendor'/, `${source} must fall back to vendor/`);
}

// `vendor/` is generated, so a source checkout may not have it. When it does,
// it must be complete and must not carry repository or runtime junk.
const vendorDir = path.join(root, 'vendor');
if (existsSync(vendorDir)) {
  const manifest = JSON.parse(await readFile(path.join(vendorDir, 'manifest.json'), 'utf8'));
  assert.ok(manifest.assets, 'vendor manifest must describe assets');
  assert.ok(!existsSync(path.join(vendorDir, 'core')), 'vendor must not carry the Python core');
  for (const relative of [
    'assets/main.bean',
    'assets/account/assets.bean',
    'assets/trans/collect.bean',
    'assets/trans/reconciliation.bean',
  ]) {
    assert.ok(existsSync(path.join(vendorDir, relative)), `vendor missing ${relative}`);
  }
  const junk = [];
  const walk = (current, prefix) => {
    for (const name of readdirSync(current)) {
      const relative = prefix === '' ? name : `${prefix}/${name}`;
      const full = path.join(current, name);
      if (statSync(full).isDirectory()) walk(full, relative);
      else if (/\.py[co]$/.test(name) || relative.split('/').some((part) => part === '__pycache__' || part === '.git')) {
        junk.push(relative);
      }
    }
  };
  walk(vendorDir, '');
  assert.deepEqual(junk, [], `vendor must not ship generated or repository files:\n${junk.join('\n')}`);
  console.log(`vendor check ok: assets @ ${manifest.assets.commit ?? 'nogit'}`);
}

// Built runtime packages are generated, so a source checkout may not have them.
// When present, their platform lock and offline payload must be complete.
const packagesDir = path.join(root, 'dist', 'packages');
if (existsSync(packagesDir)) {
  for (const [key, target] of Object.entries(runtimes.targets)) {
    const directory = path.join(packagesDir, `dsh-ledger-runtime-${key}`);
    if (!existsSync(directory)) continue;
    const descriptor = JSON.parse(await readFile(path.join(directory, 'package.json'), 'utf8'));
    assert.deepEqual(descriptor.os, [target.os], `${key} os lock`);
    assert.deepEqual(descriptor.cpu, [target.cpu], `${key} cpu lock`);
    for (const relative of ['python', 'wheelhouse', 'manifest.json']) {
      assert.ok(existsSync(path.join(directory, relative)), `${key} missing ${relative}`);
    }
    const manifest = JSON.parse(await readFile(path.join(directory, 'manifest.json'), 'utf8'));
    assert.equal(manifest.pythonVersion, runtimes.python, `${key} python version`);
    assert.ok(manifest.wheels.length > 0, `${key} wheelhouse is empty`);
    assert.deepEqual(
      manifest.core,
      { package: runtimes.core.package, version: runtimes.core.version },
      `${key} core pin`,
    );
    assert.ok(
      manifest.wheels.some((wheel) => wheel.file.startsWith('beancount_guard-')),
      `${key} wheelhouse must carry the core wheel`,
    );
  }
  console.log('runtime package check ok');
}

// Load the Client module with a minimal React/ModuleLoader shim, then run its
// registration and dictionary coverage. This catches broken registrations and
// missing locale keys without a browser.
const fakeReact = {
  createElement: () => null,
  useState: (initial) => [initial, () => {}],
  useEffect: () => {},
  useMemo: (factory) => factory(),
  useCallback: (callback) => callback,
  useRef: () => ({ current: null }),
  useSyncExternalStore: (_subscribe, read) => read(),
};
let plugin;
globalThis.window = {
  __ModuleLoader__: {
    load(spec) {
      plugin = spec.factory(() => fakeReact);
    },
  },
};
await import(`${pathToFileURL(path.join(root, 'client.js')).href}?v=${Date.now()}`);
assert.ok(plugin && Array.isArray(plugin.inject), 'client factory must return { inject, apply }');
assert.deepEqual(plugin.inject, ['slots', 'locale']);

const registrations = [];
const dictionaries = {};
plugin.apply({
  slots: {
    inject(_name, callback) {
      callback();
      return () => {};
    },
    register(options) {
      registrations.push({ options });
      return () => {};
    },
  },
  locale: {
    register(_namespace, locale, dictionary) {
      dictionaries[locale] = dictionary;
      return () => {};
    },
    bind() {
      return (key) => key;
    },
    subscribe() {
      return () => {};
    },
    getLocale() {
      return { id: 'zh' };
    },
  },
  effect(callback) {
    return callback();
  },
});
assert.ok(registrations.some(({ options }) => options.name === 'main' && options.key === 'ledger-domain'));
assert.ok(registrations.some(({ options }) => options.name === 'sidebar.panellist' && options.id === 'ledger-domain'));

const source = await readFile(path.join(root, 'client.js'), 'utf8');
const keys = new Set([...source.matchAll(/\bt\(\s*'([A-Za-z0-9_.]+)'\s*\)/g)].map((match) => match[1]));

// Contrast: a style object must not paint its text with an alias from the same
// colour family as its fill. The shell theme resolves every alias below to the
// same value (light: #0f1115, dark: #f9fafb), so `background: brand-primary`
// with `color: brand-primary-invert` painted the primary button labels in their
// own background colour. Text on a brand surface takes the inverted label alias.
const SAME_COLOUR_FAMILIES = [
  [
    '--dsw-alias-label-primary',
    '--dsw-alias-brand-primary',
    '--dsw-alias-brand-primary-invert',
    '--dsw-alias-brand-text',
  ],
];
const familyOf = (token) => SAME_COLOUR_FAMILIES.find((family) => family.includes(token));
const tokenOf = (block, property) => block.match(new RegExp(`\\b${property}:\\s*'var\\((--[\\w-]+)`))?.[1];
const clashes = [...source.matchAll(/\{[^{}]*\}/g)]
  .map((match) => match[0])
  .flatMap((block) => {
    const background = tokenOf(block, 'background');
    const color = tokenOf(block, 'color');
    if (background === undefined || color === undefined) return [];
    const family = familyOf(background);
    if (background !== color && (family === undefined || family !== familyOf(color))) return [];
    return [`${background} on ${color} — ${block.replace(/\s+/g, ' ').slice(0, 90)}`];
  });
assert.deepEqual(clashes, [], `style objects painting text with their fill colour:\n${clashes.join('\n')}`);


for (const locale of ['zh', 'en']) {
  const dictionary = dictionaries[locale];
  assert.ok(dictionary, `missing ${locale} dictionary`);
  const missing = [...keys].filter((key) => !(key in dictionary));
  assert.deepEqual(missing, [], `${locale} missing keys: ${missing.join(', ')}`);
}
console.log(`bundle check ok: ${keys.size} locale keys, ${registrations.length} registrations`);
